text:
{
  "logline": "嵐の夜、唯一の鍵が三年前に死んだ兄の石膏手形の手へ還ってしまった灯守の娘ミーナは、油が尽きる通日9日の日没までに王都で鍵と兄の真実を取り戻し、霧を招く消灯と雷を呼ぶ全灯を超える半灯を選ぶか迫られる。",
  "acts": [
    {
      "id": "setup",
      "chapters": [
        "ch01"
      ],
      "question": "ミーナは灯台に残って残りの油を見守るのか、王都の石膏の手に還った鍵を追うのか。"
    },
    {
      "id": "investigation",
      "chapters": [
        "ch02"
      ],
      "question": "ミーナは兄を臆病者とする公式記録に従うのか、証拠が示す雷の真実と非公式の半灯を受け入れるのか。"
    },
    {
      "id": "resolution",
      "chapters": [
        "ch03"
      ],
      "question": "ミーナは全灯と消灯の二択に戻るのか、教義に背いて半灯を自分の答えにするのか。"
    }
  ],
  "turns": [
    {
      "id": "t1",
      "chapter": "ch01",
      "choice_ja": "ミーナは潮鏡に映る鍵と石膏の右手を見て、父から還り鍵の理と王都に残る手形の所在を聞いたうえで、灯台に残って油の終わりを見送るのではなく、父とセスに灯皿と松明を託して自ら王都へ行くことを選ぶ。",
      "point_of_no_return": "通日2日に灯台を発てば往路3日で通日5日に王都へ着き、復路にも3日を要するため、鍵を持ち帰れる期限は通日9日の日没で閉じ、途中で引き返しても油を注ぐ手段は戻らない。"
    },
    {
      "id": "t2",
      "chapter": "ch02",
      "choice_ja": "ミーナは王都で鍵だけを回収してすぐ帰るのではなく、ヒルダに帰らぬ者の棚と削除前の記録の確認を求め、セスから託された潮札と突き合わせて兄が灯りを消した理由を確かめる道を選ぶ。",
      "point_of_no_return": "確認に通日5日を使う以上、復路3日を残して通日6日に発たなければならず、兄の真実を確かめる機会も帰還の猶予もその滞在で使い切る。"
    },
    {
      "id": "t3",
      "chapter": "ch02",
      "choice_ja": "ミーナは灯寮の公式な許可を求めず、ヒルダの私的な覚え書きと兄の潮札が示す半灯の合わせ方を受け入れ、石膏の手から鍵を自ら回収して、その刻みを灯台で使う責任を引き受けると選ぶ。",
      "point_of_no_return": "非公式の覚え書きを持って王都を発った時点で判断は彼女一人のものとなり、灯台へ戻る3日の間、灯寮に確かめ直すことも決断を預け直すこともできない。"
    },
    {
      "id": "t4",
      "chapter": "ch03",
      "choice_ja": "ミーナは通日9日の日没前に灯台へ戻り、全灯で霧だけを退ける道にも消灯で雷だけを避ける道にも従わず、鍵で灯室と油栓を開けて油を注ぎ、覚え書きどおり鍵を握ったまま半灯の刻みに合わせることを選ぶ。",
      "point_of_no_return": "三つ目の刻みを実際に使った時点で、ミーナは知らなかった娘の立場には戻れず、灯寮の教えに背く守人として自分の選択の代償を引き受ける。"
    }
  ],
  "subplots": [
    {
      "id": "oil_and_father",
      "beats": [
        "起動（ch01）：ロデリクは鍵の三つ目を壊れていると言いながら、三年前に替えた灯皿と並べた松明の油が通日9日の日没までもつという計算をミーナに明かす。",
        "干渉：ミーナの不在中、ロデリクとセスは灯皿と松明の油を数えて灯りを支えるが、油壺の減りが帰還期限の圧力を具体的な残量として示す。",
        "決着（ch03）：日没直前にミーナが戻り、ロデリクは初めて娘を止める側から半灯の操作を支える側へ回る。"
      ],
      "converges": "父とセスが稼いだ九日目までの時間が、ミーナの帰還と半灯の選択に重なる日没の場面で本筋と合流する。"
    },
    {
      "id": "brother_record",
      "beats": [
        "起動（ch01）：潮鏡は鍵を握る石膏の右手と棚の札を映すが文字は読めず、ロデリクも雷や灯寮の名が出ると話を切るため、兄への疑問は手つかずで残る。",
        "干渉（ch02）：ヒルダは棚札と削除前の草稿を突き合わせ、ヨハンが雷から港町を守るために灯りを消したことを示し、兄の潮札にある半灯の記述がその判断を裏づける。",
        "決着（ch03）：ミーナは公的な記録訂正を持ち帰る代わりに、兄が残した半灯を実行することで、その選択を自分の務めとして受け継ぐ。"
      ],
      "converges": "兄の真実が感情的な決着にとどまらず、ミーナが全灯ではなく半灯を選ぶ実践的な理由として本筋の結末に合流する。"
    },
    {
      "id": "seth_tide_tag",
      "beats": [
        "起動（ch01）：セスは三年前の浜で拾った文字のかすれた潮札を読めたふりで補わず、そのままミーナへ託す。",
        "干渉（ch02）：ミーナは王都で潮札とヒルダの覚え書きを合わせ、半灯へ回す順番と『嵐の夜は握ったまま』という条件を読み取る。",
        "決着（ch03）：ミーナが順番どおりに鍵を握ったまま操作し、灯台に残ったセスは託した札が灯りを継いだことを見届ける。"
      ],
      "converges": "セスが三年運んだ読めない札が、鍵を回収した後の最終操作に必要な手順を与え、第四の転換点で本筋と合流する。"
    }
  ],
  "ending": {
    "kind": "bittersweet",
    "summary": "ミーナは通日9日の日没前に鍵を持ち帰って油を注ぎ、半灯によって霧を退けつつ雷を呼ばずに灯りを継ぎ、還り鍵の理を解く。港町は守られるが兄は戻らず、灯寮の公式記録もその夜には改まらない。",
    "aftertaste_ja": "救われた灯りの下で、守ることは言われたとおりに従うことではなく、代償を知ったうえで選び続けることだという静かな重さが残る。"
  },
  "unresolved": [
    {
      "item": "灯寮の公式記録ではヨハンが臆病者とされたままとなり、公的な名誉回復は作中で果たされない。",
      "foreshadowing": "fs-004",
      "intentional": true
    },
    {
      "item": "ミーナとロデリクが半灯を使った事実を灯寮が知ったときに受ける処分は描かれない。",
      "foreshadowing": "fs-001",
      "intentional": true
    }
  ]
}
